### Etape 6 : Creer le wrapper PatientNavigation (patient-navigation.tsx)

```typescript
import { SidebarInset, SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { Layout } from "@/features/page/layout";
import type { PropsWithChildren } from "react";
import { PatientSidebar } from "./patient-sidebar";
import { PatientMobileNav } from "./patient-mobile-nav";

export async function PatientNavigation({ children }: PropsWithChildren) {
  return (
    <SidebarProvider>
      <PatientSidebar />
      <SidebarInset className="border-accent border bg-[#F8F7F3]">
        <header className="flex h-16 shrink-0 items-center gap-2 md:hidden">
          <Layout size="lg" className="flex items-center gap-2">
            <SidebarTrigger className="-ml-1" />
          </Layout>
        </header>
        <div className="flex flex-1 flex-col gap-4 p-4 pt-0 pb-20 md:pb-4">
          {children}
        </div>
      </SidebarInset>
      <PatientMobileNav />
    </SidebarProvider>
  );
}
```

